('monetization',('创业游戏公司 · 海外商业化','Game startup · Overseas monetization'),('ARPU +70% · 付费转化 +50%','ARPU +70% · Payer conversion +50%'),('海外ROI未跑正、内购转化低。调整虚拟商品推荐、付费点和转化路径后，核心地区ROI开始跑正，并落地版金及预付款。','Overseas ROI was negative and in-app purchase conversion was low. Changes to virtual-goods recommendations, offers and purchase paths increased ARPU and payer conversion; key markets moved to positive ROI, with licensing and advance payments secured.'),'AI商业化BP · P08'),
('membership',('会员制业务 · 游戏化经营','Membership business · Gamified operations'),('活跃用户 +65% · 会员单客价值 +42%','Active users +65% · Member value +42%'),('以任务、累计消费奖励、社交传播及AI行为反馈改造转化路径，60天形成游戏化模块，支持本地及国际会员。','Tasks, cumulative-spend rewards, social sharing and AI-assisted behavioral feedback reshaped conversion. A gamification module serving local and international members was completed in 60 days.'),'AI商业化BP · P18'),
('validation',('自研AI游戏SOP工具 · 研发验证','Proprietary AI game SOP tools · Validation'),('验证 2个月→5天 · 研发成本节省 >80%','Validation: 2 months → 5 days · R&D cost savings >80%'),('3天完成20多个交互Demo，1天完成App上线，取得首轮真实留存与LTV数据。','Produced 20+ interactive demos in three days, launched an app in one day and obtained first-round retention and LTV data.'),'AI商业化BP · P18'),
('kol',('出海产品 · KOL自动化分发','Overseas products · Automated KOL distribution'),('投放成本约为市场价 1/3','Campaign cost around one-third of market rates'),('3天触达10,000多个本地KOL；3,000元获得10,000多个有效用户转化。该数字沿用原项目的有效转化定义，不等同付费用户数。','Reached 10,000+ local KOLs in three days. RMB3,000 delivered 10,000+ effective user conversions under the project’s original conversion definition; this is not a paying-user count.'),'AI商业化BP · P18'),
('publisher',('超轻休闲游戏发行公司','Hypercasual / casual publisher'),('停滞半年后 · 1个月投产跑正','After six stalled months · Positive returns in 1 month'),('项目筹备2年、停滞半年。约1周半建立产品引入流程，重启发行与商业化，1个月投产跑正。','After two years of preparation and six stalled months, a product-intake process was established in about 1.5 weeks. Publishing and monetization restarted, reaching positive returns in one month.'),'业务介绍BP v1.4 · P17'),
('blockchain',('区块链游戏 · 经营重整','Blockchain game · Operating turnaround'),('6周 · 实现半年来首次收入增长','6 weeks · First revenue growth in six months'),('重建工作室、完成产品交接，协同运营、研发及市场，恢复收入增长。','Rebuilt the studio and product handover process, aligning operations, development and marketing to restore revenue growth.'),'业务介绍BP v1.4 · P17'),
('app',('App公司 · 海外业务','App company · Overseas operations'),('接手后 2个月跑正','Positive returns within 2 months'),('对接渠道与投放资源，调整推广、传播及产品体验，接手后2个月跑正。','Connected channels and media resources, then improved promotion, distribution and the product experience to achieve positive returns within two months.'),'业务介绍BP v1.4 · P17'),
('publishing',('直播与游戏 · 海外发行','Live entertainment & games · Overseas publishing'),('上线6款 · 其中3款跑正','6 titles launched · 3 reached positive returns'),('1个月建立发行运营、商务团队与平台；引入10余款产品，上线6款，其中3款跑正。','Built the publishing, operations and BD team and platform in one month. Sourced 10+ titles, launched six and brought three to positive returns.'),'业务介绍BP v1.4 · P17'),
('cp',('休闲游戏发行公司 · CP供给','Casual publisher · Developer supply'),('3周建立发行流程 · 6周形成投放产出','Publishing process in 3 weeks · Campaign output in 6'),('梳理细分品类CP、建立发行及投放规范，6周开始接入CP并形成投放产出。','Mapped category-specific developers and built publishing and media standards, beginning developer onboarding and campaign output within six weeks.'),'业务介绍BP v1.4 · P17'),
('newgame',('中型非游戏公司 · 新游戏出海','Mid-sized non-game company · New overseas game'),('局部地区 ROI 跑正','Positive ROI in selected regions'),('游戏研发超过一年。重做用户定位、产品市场适配、数值框架及欧美投放和本地化，进入持续迭代。','After over a year of development, player positioning, product-market fit, the economy, Western-market acquisition and localization were revised, achieving positive ROI in selected regions.'),'AI商业化BP · P08'),
