METRICS=[('验证周期','Validation cycle','10周 → 4周','10 → 4 weeks','−60%'),('研发试错成本','R&D trial cost','100万 → 55万','1m → 0.55m','−45%'),('素材测试数量','Creative tests','50 → 160','50 → 160','+220%'),('CTR','CTR','1.2% → 1.62%','1.2% → 1.62%','+35%'),('LTV','LTV','US$12.5 → US$16','US$12.5 → US$16','+28%')]

def txt(pair,loc):
 if loc:return e(pair[0 if loc=='zh' else 1])
 return '<span class="proof-zh" lang="zh">'+e(pair[0])+'</span><span class="proof-en" lang="en">'+e(pair[1])+'</span>'
def result_cases(loc,compact,section):
 t=lambda z,en:txt((z,en),loc)
 cards=''
 for key,title,outcome,action,source in (KPI[:4] if compact else KPI):
  cards+='<article class="proof-case kpi-case" id="kpi-'+key+'"><p class="proof-tag">'+txt(title,loc)+'</p><h3>'+txt(outcome,loc)+'</h3><details><summary>'+t('查看背景、做法与结果','Read context, actions and results')+'</summary><p>'+txt(action,loc)+'</p><p class="proof-note">'+t('来源：'+source, 'Source: original GGC business presentation')+'</p></details></article>'
 body='<div class="proof-grid">'+cards+'</div>'
 if compact:body+='<p class="proof-next"><a href="about.html#case-library">'+t('查看全部14组客户与工具应用案例 →','Explore all 14 client and tool-application cases →')+'</a></p>'
 else:
  body+='<h3 class="proof-subhead">'+t('另一组历史项目：五项前后对比','Another historical project: five before-and-after measures')+'</h3><div class="kpi-metrics">'+''.join('<article><h4>'+t(z,en)+'</h4><strong>'+t(before,before_en)+'</strong><b>'+change+'</b></article>' for z,en,before,before_en,change in METRICS)+'</div><p class="proof-note">'+t('来源：29页BP P17，为独立历史项目；研发试错成本原页未标币种。CTR为相对提升35%（增加0.42个百分点）；测试数量为原来的3.2倍。','Source: 29-page presentation, p17; an independent historical project. The R&D cost currency was not specified. CTR rose 35% relatively (0.42 percentage points); test volume reached 3.2× the baseline.')+'</p>'
 body+='<p class="proof-note">'+t('以上为GGC原业务材料中的历史案例，按项目分别计量；客户名称脱敏，结果不自动对应下方Logo。','Historical cases from GGC’s business materials, measured separately by project. Client names are anonymized; results are not automatically attributed to the logos below.')+'</p>'
 return section('case-library','CLIENT RESULTS / KPI',('把经营改善，落实到KPI。','Operating improvements, measured in KPIs.'),('成本、ROI、ARPU、付费转化与验证周期：先看结果，再看怎样做到。','Cost, ROI, ARPU, payer conversion and validation time: results first, then the operating work behind them.'),body,loc)

def ai_results(loc):
 t=lambda z,en:txt((z,en),loc)
 return '<div class="proof-grid kpi-ai"><article class="proof-case"><p class="proof-tag">GGC · '+t('历史投放实测','Historical campaign test')+'</p><h3>'+t('市场参考 US$2–3 → GGC 几美分','Market reference US$2–3 → GGC a few US cents')+'</h3><p>'+t('AI辅助投放的单价对比，金额均为美元；按该历史测试的同一投放事件比较。','AI-assisted campaign unit-cost comparison, in US dollars, using the same campaign event within this historical test.')+'</p></article><article class="proof-case"><p class="proof-tag">AI · '+t('研发验证','Development validation')+'</p><h3>'+t('2个月 → 5天 · 成本节省 >80%','2 months → 5 days · Cost savings >80%')+'</h3><p>'+t('自研游戏SOP工具应用：3天完成20多个交互Demo，取得首轮留存及LTV数据。','Proprietary game SOP tool application: 20+ interactive demos in three days, with first-round retention and LTV data.')+'</p></article></div>'

def logos(loc,section):
 t=lambda z,en:txt((z,en),loc)
 def grid(names,kind):
  return '<div class="proof-logos">'+''.join('<figure><img src="'+('/joyce/assets/bp-logos/' if loc is None else '../assets/bp-logos/')+f'{kind}-{i:02}.webp" alt="'+e(name)+'" width="280" height="130" loading="lazy"><figcaption>'+e(name)+'</figcaption></figure>' for i,name in enumerate(names,1))+'</div>'
 body='<h3 class="proof-subhead">'+t('部分客户','Selected clients')+'</h3>'+grid(CLIENTS,'client')+'<h3 class="proof-subhead">'+t('合作伙伴','Partners')+'</h3>'+grid(PARTNERS,'partner')+'<p class="proof-note">'+t('媒体合作：扬帆出海 · 白鲸出海 · Enjoy出海 · 快出海。名单及Logo按原业务BP“部分客户／合作伙伴示例”展示。','Media partners: Yangfan · Baijing · Enjoy · KCHUHAI. Names and logos follow the original business presentation’s selected-client and partner pages.')+'</p>'
 return section('clients-partners','CLIENTS & PARTNERS',('与客户同行，与伙伴共建。','Working with clients. Building with partners.'),('游戏、泛娱乐、金融与企业服务，以及全球平台、数据、技术与媒体伙伴。','Across games, entertainment, finance and business services, with global platform, data, technology and media partners.'),body,loc)
CSS=""".kpi-case h3{color:var(--proof-accent);font-size:27px;line-height:1.5}.kpi-metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.kpi-metrics article{border:1px solid var(--proof-line);border-radius:14px;padding:20px 14px;background:var(--proof-bg)}.kpi-metrics h4{font-size:14px;margin:0 0 12px}.kpi-metrics strong,.kpi-metrics b{display:block;line-height:1.6}.kpi-metrics b{color:var(--proof-accent);font-size:24px;margin-top:12px}.proof-logos{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:16px}.proof-logos figure{margin:0;padding:16px 10px;background:#fff;border:1px solid var(--proof-line);border-radius:14px;text-align:center}.proof-logos img{width:100%;height:100px;object-fit:contain}.proof-logos figcaption{font-size:12px;line-height:1.6;margin-top:12px;overflow-wrap:anywhere}.kpi-ai{margin-bottom:38px}@media(max-width:800px){.kpi-metrics,.proof-logos{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:540px){.kpi-metrics,.proof-logos{grid-template-columns:repeat(2,minmax(0,1fr))}.kpi-case h3{font-size:24px}.proof-logos img{height:78px}}"""
